WITH filtered AS (SELECT *, ROUND(monthly_fee * 100, 2) AS monthly_fee_adjusted, ROUND(monthly_fee * 1.1, 2) AS monthly_fee_adjusted_2 FROM subscriptions WHERE plan = 'standard') SELECT id, plan, measure, value FROM (SELECT id, plan, monthly_fee_adjusted, monthly_fee, monthly_fee_adjusted_2 FROM filtered) src UNPIVOT (value FOR measure IN (monthly_fee_adjusted, monthly_fee, monthly_fee_adjusted_2));
